### 3. CDC 데이터 흐름 및 카테고리 처리

#### 3-1. CDC Event 수신

**파일:** `/Users/admin/project/integrated-search/inbound-adapter/handler/src/main/kotlin/com/cowave/search/inbound_adapter/handler/listener/ProductDynamicIndexListener.kt`

```kotlin
class ProductDynamicIndexListener(...) : BatchAcknowledgingConsumerAwareMessageListener {
    override fun onMessage(
        data: List<ConsumerRecord<SpecificRecord, SpecificRecord>>,
        acknowledgment: Acknowledgment?,
        consumer: Consumer<*, *>,
    ) {
        val changedDocuments = data
            .filter { record ->
                val envelope = record.value() as ProductCdcEnvelope
                val product = envelope.after ?: envelope.before
                product != null && product.categoryId > 0  // categoryId 검증
            }
            .map { it.toChangedProductData() }

        productIndexApplicationService.indexProducts(changedDocuments)
    }
}
```

#### 3-2. ChangedProductDocument 구조

**파일:** `/Users/admin/project/integrated-search/domain/index/src/main/kotlin/com/cowave/search/domain/index/dto/ChangedProductDocument.kt`

```kotlin
data class ChangedProductDocument(
    @field:JsonProperty("_id")
    override val id: String,
    override val name: String,
    val categoryId: Int,          // leaf category ID만 존재
    val brandId: Long?,
    val manufacturerId: Long?,
    // ... 다른 필드
    val channelDatas: ChannelDatas,
) : ChangedDocument
```

**핵심:** CDC에서는 `categoryId`(단일 값, leaf category)만 제공

#### 3-3. 카테고리 조회 및 매핑 (Application Layer)

**파일:** `/Users/admin/project/integrated-search/application/index/src/main/kotlin/com/cowave/search/application/index/service/ProductAssembleService.kt`

```kotlin
@Service
class ProductAssembleService(
    private val proxyApplicationService: ProxyApplicationService,
) {
    fun assemble(documents: List<ChangedData<ChangedProductDocument>>): List<IndexDocument<ProductDocument>> {
        // 1. 문서들에서 필요한 의존성 ID 추출
        val dependencyId = getDependencyId(documents)

        // 2. Proxy API로부터 카테고리, 브랜드, 제조사 조회
        val dependency = proxyApplicationService.fetchDependencies(dependencyId)

        // 3. 각 문서에 조회된 카테고리 정보 매핑
        return documents.map {
            if (it.op == Operation.CREATE) {
                require(dependency.categories[it.afterData!!.categoryId] != null) {
                    "Failed to assemble product. Category must not be null."
                }
            }

            it.toIndexDocument(
                category = dependency.categories[it.afterData?.categoryId],
                brand = dependency.brands[it.afterData?.brandId],
                manufacturer = dependency.manufacturers[it.afterData?.manufacturerId],
            )
        }
    }

    fun getDependencyId(documents: List<ChangedData<ChangedProductDocument>>): DependencyId {
        val categoryIds: MutableList<Int> = mutableListOf()
        documents.forEach {
            if (it.shouldFetchCategory) {
                categoryIds.add(it.afterData!!.categoryId)
            }
        }
        return DependencyId(
            categoryIds = categoryIds.distinct(),
            // ...
        )
    }
}
```

#### 3-4. ProxyApplicationService (병렬 조회)

**파일:** `/Users/admin/project/integrated-search/application/index/src/main/kotlin/com/cowave/search/application/index/service/ProxyApplicationService.kt`

```kotlin
@Service
class ProxyApplicationService(
    private val categoryService: CategoryService,
    private val brandService: BrandService,
    private val manufacturerService: ManufacturerService,
) {
    fun fetchDependencies(dependencyId: DependencyId): Dependency =
        runBlocking(Dispatchers.IO) {
            // 병렬로 카테고리 조회
            val categoriesDeferred = async {
                if (dependencyId.categoryIds.isEmpty()) {
                    emptyMap()
                } else {
                    categoryService.getCategories(dependencyId.categoryIds)
                        .associateBy { it.id }  // Map<Int, Category>
                }
            }

            // 결과 대기
            Dependency(
                categories = categoriesDeferred.await(),
                brands = brandsDeferred.await(),
                manufacturers = manufacturersDeferred.await(),
                malls = mallsDeferred.await(),
            )
        }
}
```

#### 3-5. IndexDocument 생성 (카테고리 계층 적용)

**파일:** `/Users/admin/project/integrated-search/application/index/src/main/kotlin/com/cowave/search/application/index/mapper/ProductIndexDocumentMapper.kt`

```kotlin
fun ChangedProductDocument.toProductDocument(
    category: Category,
    brand: Brand?,
    manufacturer: Manufacturer?,
): ProductDocument = with(this) {
    ProductDocument(
        id = id,
        name = name,
        categoryId = categoryId,              // leaf category
        categoryId1 = category.categoryId1,   // 1차 카테고리
        categoryId2 = category.categoryId2,   // 2차 카테고리
        categoryId3 = category.categoryId3,   // 3차 카테고리
        categoryId4 = category.categoryId4,   // 4차 카테고리
        categoryNames = category.categoryNames, // "전자기기 스포츠용품 수상용품 물안경"
        categoryStatus = category.status,
        // ... 다른 필드
    )
}
```

