### 4. 레거시 ES 역싱크 흐름

**파일:** `/Users/admin/project/integrated-search/application/index/src/main/kotlin/com/cowave/search/application/index/service/ProductIndexApplicationService.kt`

```kotlin
@Service
class ProductIndexApplicationService(
    private val productIndexRepository: ProductIndexRepository,
    private val productAssembleService: ProductAssembleService,
    private val legacySyncRepository: LegacySyncRepository?,  // Optional
) {
    fun indexProducts(changedData: List<ChangedData<ChangedProductDocument>>): IndexResult {
        // 1. 메인 ES 색인
        val indexDocuments = changedData
            .let(ProductMergeStrategy::merge)
            .let { productAssembleService.assemble(it) }  // 카테고리 조회 포함
            .filter(ProductEvaluator::evaluate)

        val result = productIndexRepository.bulk(indexDocuments)

        // 2. 레거시 ES 역싱크 (Fail-Safe)
        legacySyncRepository?.syncProducts(changedData)

        return result
    }
}
```

**파일:** `/Users/admin/project/integrated-search/outbound/client/legacy-es-sync/src/main/kotlin/com/cowave/search/client/legacy_es_sync/mapper/LegacyRequestMapper.kt`

```kotlin
@Component
class LegacyRequestMapper {
    fun toGroupedRequests(changedDataList: List<ChangedData<ChangedProductDocument>>): List<GroupedLegacySyncRequest> {
        return changedDataList
            .mapNotNull { changedData -> toSingleRequest(changedData) }
            .groupBy { it.operation to it.serviceType }
            .map { (key, requests) ->
                GroupedLegacySyncRequest(
                    serviceType = key.second,
                    operation = key.first,
                    payloads = requests.map { it.payload },
                )
            }
    }

    private fun toSingleRequest(changedData: ChangedData<ChangedProductDocument>): LegacySyncRequest? {
        val document = changedData.afterData ?: changedData.beforeData ?: return null

        // Note: 현재는 categoryId를 직접 전달하지 않음
        // shopCode와 mallProductId만 전달
        val payload = if (document.isCatalogMatch) {
            LinkProductRequest(
                shopCode = MallCodeMapping.getShopCodeOrNull(document.mallId),
                shopProductCode = document.mallProductId,
            )
        } else {
            UnlinkProductRequest(
                shopCode = shopCode,
                shopProductCode = document.mallProductId,
                productName = document.name,
                // ...
            )
        }
        return LegacySyncRequest(operation = changedData.op, payload = payload)
    }
}
```

**현재 상태:** 레거시 역싱크에는 카테고리 정보가 포함되지 않음 (shopCode, 상품ID, 가격 등만)

